-- 596: Original BrillaPrep Cambridge IGCSE Chemistry (0620) sprint 3 beta questions, part 3 of 13 (batch igcse-chemistry-sprint3-001).
-- Curriculum-aligned practice content; not official Cambridge International, WAEC or NSMQ examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_596_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_596_guard;
INSERT INTO _migration_596_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_009' AND NOT (q.topic_id IS 'topic_igcse_chem_periodic' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following elements is a noble gas?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Nitrogen","B. Chlorine","C. Sodium","D. Argon"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Argon is in Group 0 (Group 18), the noble gases, with a full outer shell of electrons. (Nitrogen and chlorine are reactive non-metals; sodium is an alkali metal.) Therefore the correct answer is D: Argon.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_009' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_596_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_010' AND NOT (q.topic_id IS 'topic_igcse_chem_periodic' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A sample of chlorine contains 75% of the isotope ³⁵Cl and 25% of the isotope ³⁷Cl. Calculate the relative atomic mass of the chlorine in the sample.' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '35.5' AND q.explanation IS 'Relative atomic mass = (percentage × mass number) for each isotope, summed, divided by 100: (75 × 35 + 25 × 37) ÷ 100 = (2,625 + 925) ÷ 100 = 3,550 ÷ 100 = 35.5. Answer: the relative atomic mass is 35.5.' AND q.difficulty IS 'medium' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_010' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_596_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_011' AND NOT (q.topic_id IS 'topic_igcse_chem_bonding' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which substance contains only covalent bonds?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Methane, CH₄","B. Sodium chloride, NaCl","C. Magnesium oxide, MgO","D. Calcium fluoride, CaF₂"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Methane contains a non-metal bonded to a non-metal, so its atoms share electrons covalently. (NaCl, MgO and CaF₂ are metal–non-metal compounds with ionic bonding.) Therefore the correct answer is A: Methane, CH₄.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_011' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_596_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_012' AND NOT (q.topic_id IS 'topic_igcse_chem_bonding' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solid sodium chloride does not conduct electricity, but molten sodium chloride does. Which statement explains this?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Electrons flow through the molten lattice.","B. The ions are free to move in the molten state.","C. The ions gain extra electrons when the solid melts.","D. Sodium chloride becomes a metal when it melts."]' AND q.correct_answer IS 'B' AND q.explanation IS 'Ionic solids conduct only when their charged ions can move. Melting breaks up the lattice so the ions become mobile and carry the current. (Ionic compounds conduct by moving ions, not electrons; melting supplies energy, not electrons.) Therefore the correct answer is B: The ions are free to move in the molten state..' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_012' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_009', 'topic_igcse_chem_periodic', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Which of the following elements is a noble gas?', 'multiple_choice', NULL, '["A. Nitrogen","B. Chlorine","C. Sodium","D. Argon"]', 'D', 'Argon is in Group 0 (Group 18), the noble gases, with a full outer shell of electrons. (Nitrogen and chlorine are reactive non-metals; sodium is an alkali metal.) Therefore the correct answer is D: Argon.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_010', 'topic_igcse_chem_periodic', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'A sample of chlorine contains 75% of the isotope ³⁵Cl and 25% of the isotope ³⁷Cl. Calculate the relative atomic mass of the chlorine in the sample.', 'calculation', NULL, NULL, '35.5', 'Relative atomic mass = (percentage × mass number) for each isotope, summed, divided by 100: (75 × 35 + 25 × 37) ÷ 100 = (2,625 + 925) ÷ 100 = 3,550 ÷ 100 = 35.5. Answer: the relative atomic mass is 35.5.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_011', 'topic_igcse_chem_bonding', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Which substance contains only covalent bonds?', 'multiple_choice', NULL, '["A. Methane, CH₄","B. Sodium chloride, NaCl","C. Magnesium oxide, MgO","D. Calcium fluoride, CaF₂"]', 'A', 'Methane contains a non-metal bonded to a non-metal, so its atoms share electrons covalently. (NaCl, MgO and CaF₂ are metal–non-metal compounds with ionic bonding.) Therefore the correct answer is A: Methane, CH₄.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_012', 'topic_igcse_chem_bonding', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Solid sodium chloride does not conduct electricity, but molten sodium chloride does. Which statement explains this?', 'multiple_choice', NULL, '["A. Electrons flow through the molten lattice.","B. The ions are free to move in the molten state.","C. The ions gain extra electrons when the solid melts.","D. Sodium chloride becomes a metal when it melts."]', 'B', 'Ionic solids conduct only when their charged ions can move. Melting breaks up the lattice so the ions become mobile and carry the current. (Ionic compounds conduct by moving ions, not electrons; melting supplies energy, not electrons.) Therefore the correct answer is B: The ions are free to move in the molten state..', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge');
